19	/**
20	 * Retrieves the assistant configuration (supportedFeatures and metadata).
21	 * Note: Prompt composition is handled by pipecat-daily-bot, not the interface.
22	 *
23	 * @param subDomain - The subdomain identifier for the assistant.
24	 * @param _clientLanguage - Unused, kept for backwards compatibility.
25	 * @param _userName - Unused, kept for backwards compatibility.
26	 * @param _userProfile - Unused, kept for backwards compatibility.
27	 * @param _sessionHistory - Unused, kept for backwards compatibility.
28	 * @returns A promise resolving to supportedFeatures and assistant metadata.
29	 */
30	export const getAssistantConfig = async (
31	  subDomain: string,
32	  _clientLanguage: string = 'en',
33	  _userName: string,
34	  _userProfile: Record<string, any> = {},
35	  _sessionHistory: Array<any> = []
36	): Promise<{ supportedFeatures: FeatureKey[] }> => {
37	  const log = getLogger('getAssistant');
38	  log.info('Fetching assistant config', { subDomain });
39	
40	  // Normalize name for name-based lookup: capitalize first letter, lowercase the rest
41	  const normalizedName = subDomain ? subDomain.charAt(0).toUpperCase() + subDomain.slice(1).toLowerCase() : subDomain;
42	  let assistant = await getAssistantBySubDomain(subDomain) || await getAssistantByName(normalizedName);
43	  
44	  // If no assistant is found, find or create a default assistant configuration
45	  if (!assistant || !assistant._id) {
46	    log.warn('No assistant found, using default', { subDomain });
47	    assistant = await getDefaultAssistant(interfaceAuthOptions);
48	  } else if (!assistant.subDomain) {
49	    log.warn('Assistant has no subDomain', { id: assistant._id });
50	  }
51	
52	  const supportedFeatures = coerceFeatureKeyList((assistant.supportedFeatures as unknown) ?? []);
53	  // Hardwire openclawBridge — bypass fragile feature flag chain
54	  if (!supportedFeatures.includes('openclawBridge')) {
55	    supportedFeatures.push('openclawBridge' as FeatureKey);
56	  }
57	  // Hardwire wonderCanvas feature flag
58	  if (!supportedFeatures.includes('wonderCanvas' as FeatureKey)) {
59	    supportedFeatures.push('wonderCanvas' as FeatureKey);
60	  }
61	  // Hardwire summonSpriteTool — sprite generation via ComfyUI
62	  if (!supportedFeatures.includes('summonSpriteTool' as FeatureKey)) {
63	    supportedFeatures.push('summonSpriteTool' as FeatureKey);
64	  }
65	  // Hardwire summonSpriteTool feature flag
66	  if (!supportedFeatures.includes('summonSpriteTool' as FeatureKey)) {
67	    supportedFeatures.push('summonSpriteTool' as FeatureKey);
68	  }
69	  // Hardwire avatar so the voice/call button always renders
70	  if (!supportedFeatures.includes('avatar' as FeatureKey)) {
71	    supportedFeatures.push('avatar' as FeatureKey);
72	  }
73	  // Hardwire desktop app icons so they always appear (especially in chat/touch mode)
74	  for (const feat of ['notes', 'htmlContent', 'miniBrowser', 'youtube', 'dailyCall', 'vision'] as FeatureKey[]) {
75	    if (!supportedFeatures.includes(feat)) {
76	      supportedFeatures.push(feat);
77	    }
78	  }
79	  return {
80	    supportedFeatures,
81	  };
82	};
